      propPathParts = propPath.split('.')
    }
    const fieldPath = [objectName, ...propPathParts].join(' / ')
    console.log('Track:', fieldPath, '-> keyframes:', trackData.keyframes.map(k => `${k.position}s=${k.value}`).join(', '))
  }
}

